export const messages = [
  {id: "a", conversationId: "chat-1", createdAtMicros: "1700000000123401"},
  {id: "b", conversationId: "chat-1", createdAtMicros: "1700000000123402"},
  {id: "c", conversationId: "chat-1", createdAtMicros: "1700000000123402"},
  {id: "d", conversationId: "chat-1", createdAtMicros: "1700000000123403"}
];

export function encodeCursor(row) {
  return {createdAt: new Date(Number(row.createdAtMicros) / 1000).toISOString(), id: row.id};
}

export function page(rows, cursor, direction, limit) {
  const cursorMicros = BigInt(Date.parse(cursor.createdAt)) * 1000n;
  const filtered = rows.filter((row) => {
    const micros = BigInt(row.createdAtMicros);
    const comparison = micros === cursorMicros ? row.id.localeCompare(cursor.id) : micros < cursorMicros ? -1 : 1;
    return direction === "older" ? comparison < 0 : comparison > 0;
  });
  return direction === "older" ? filtered.slice(-limit) : filtered.slice(0, limit);
}

export function selectContext(owner, conversation, anchorId) {
  if (conversation.ownerId !== owner.id) throw new Error("forbidden");
  const rows = messages.filter((row) => row.conversationId === conversation.id);
  const index = rows.findIndex((row) => row.id === anchorId);
  if (index < 0) throw new Error("not found");
  const visible = rows.slice(Math.max(0, index - 1), index + 2);
  return {anchorId, visible, olderCursor: encodeCursor(visible[0]), newerCursor: encodeCursor(visible.at(-1))};
}

export function refetchContext(state, fetchLatest) {
  const visible = fetchLatest();
  return {anchorId: state.anchorId, visible, olderCursor: encodeCursor(visible[0]), newerCursor: null};
}

