class MemoryFs:
    """An in-memory adapter; no method performs an OS filesystem operation."""
    def __init__(self):
        self.links = {"installed/shared-tool": "shared/tool"}
        self.trees = {
            "shared/tool": {"manifest.json": "shared manifest", "saved-output.txt": "retained work"},
            "installed/generated-tool": {"manifest.json": "generated wrapper"},
        }

    def resolve(self, entry):
        return self.links.get(entry, entry)

    def is_symlink(self, entry):
        return entry in self.links

    def is_dir(self, entry):
        return self.resolve(entry) in self.trees

    def unlink(self, entry):
        del self.links[entry]

    def remove_tree(self, resolved_directory):
        del self.trees[resolved_directory]

