def setup():
    db=sqlite3.connect(':memory:')
    db.executescript('CREATE TABLE parents(tenant TEXT,id INTEGER,PRIMARY KEY(tenant,id)); CREATE TABLE lines(tenant TEXT,parent_id INTEGER,amount INTEGER);')
    db.executemany('INSERT INTO parents VALUES(?,?)',[('red',i) for i in range(1,13)])
    db.executemany('INSERT INTO lines VALUES(?,?,?)',[('red',i,i*10) for i in range(1,12)]+[('blue',1,900)])
    return db

def baseline(db,limit):
    parents=db.execute('SELECT id FROM parents WHERE tenant=? ORDER BY id LIMIT ?',('red',limit)).fetchall()
    return [(key,db.execute('SELECT COALESCE(SUM(amount),0) FROM lines WHERE tenant=? AND parent_id=?',('red',key)).fetchone()[0]) for key, in parents]

def proposed(db,limit):
    return db.execute('SELECT p.id,SUM(l.amount) FROM parents p JOIN lines l ON p.id=l.parent_id WHERE p.tenant=? GROUP BY p.id ORDER BY p.id LIMIT ?',('red',limit)).fetchall()

results=[]
for limit in (4,12):
    measures={}
    for name,fn in [('baseline',baseline),('proposed',proposed)]:
        db=setup();samples=[];queries=[];rows=None
        for _ in range(7):
            statements=[];db.set_trace_callback(statements.append)
            start=time.perf_counter_ns();rows=fn(db,limit);samples.append(time.perf_counter_ns()-start)
            queries.append(len([s for s in statements if s.startswith('SELECT')]))
        measures[name]={'rows':rows,'query_counts':queries,'samples_ns':samples,'median_ns':statistics.median(samples)}
        db.close()
    results.append({'parent_limit':limit,'measurements':measures,'outputs_equal':measures['baseline']['rows']==measures['proposed']['rows']})
print(json.dumps({'engine':'SQLite','version':sqlite3.sqlite_version,'runtime_clock':'perf_counter_ns','scope':'small local fixture, no network or capacity measurement','results':results}))
